// cualquier columna que no figure acá se importa con su nombre tal cual viene.
const STYLE_ALIASES = {
    'honey':          'HONEY 🍯',
    'coco amber ale': 'COCO AMBER ALE 🥥',
    'caipi lager':    'CAIPI LAGER 🍋',
    'kai':            'KAI 0%',
    'barley':         'BARLEY WINE',
    'doble jammin':   'DOBLE JAMMIN IPA',
};

// Columnas de la planilla que no son estilos (uso interno de BOHR).
const INTERNAL_HEADERS = new Set(['cliente', 'comentarios negrito', 'comentarios']);

const normKey = s => String(s).toLowerCase().replace(/\s+/g, ' ').trim();

function canonicalStyleName(header) {
    const clean = String(header).replace(/\s+/g, ' ').trim();
    return STYLE_ALIASES[normKey(clean)] || clean.toUpperCase();
}

function defaultDescFor(styleName) {
    return DEFAULT_BEER_STYLES.find(s => s.name === styleName)?.desc || '';
}

